const webhookBody = $('Webhook AgroVenda').first().json.body || {};
const folderId = $('Criar ou Usar Pasta da Loja no Drive').first().json.id;
const saleId = String(webhookBody.saleId || '');
const romaneio = String(webhookBody.romaneioNumber || '').replace(/\D/g, '');
const nfDigits = String(webhookBody.nfNumber || '').replace(/\D/g, '');
const incoming = Array.isArray(webhookBody.files) ? webhookBody.files : [];

// Arquivos já na pasta (saída do nó Listar)
const existingItems = (() => {
  try {
    return $('Listar Arquivos da Pasta da Venda').all().map((i) => i.json).filter((j) => j && (j.id || j.name || j.Name));
  } catch (e) {
    return [];
  }
})();

function baseName(n) {
  return String(n || '').split('/').pop();
}

function extractNf(name) {
  const n = baseName(name);
  const m1 = n.match(/NF-(\d{6,12})/i);
  if (m1) return m1[1];
  const m2 = n.match(/(?:^|[-_\s])(\d{7,9})(?:[-_\s.]|$)/);
  return m2 ? m2[1] : '';
}

function extractRom(name) {
  const n = baseName(name);
  const m1 = n.match(/^(\d{3,6})-(?:NF|Pedido|CP)/i);
  if (m1) return m1[1].padStart(5, '0');
  const m2 = n.match(/Pedido-(\d{3,6})/i);
  return m2 ? m2[1].padStart(5, '0') : '';
}

function kindOf(name) {
  const n = baseName(name).toLowerCase();
  if (/\bnf[-_]|-nf-/.test(n) || /lancada/.test(n)) return 'nf';
  if (/pedido|canhoto/.test(n)) return 'pedido';
  if (/\bcp[-_]|comprovante/.test(n)) return 'cp';
  return 'other';
}

const existingExact = new Set(existingItems.map((e) => baseName(e.name || e.Name || '')));
const trashIds = new Set();

for (const e of existingItems) {
  const name = baseName(e.name || e.Name || '');
  const id = e.id || e.Id;
  if (!id || !name) continue;
  const k = kindOf(name);
  const eNf = extractNf(name);
  const eRom = extractRom(name);
  const isLegacyVp = /^VP\d+/i.test(name);
  const sameNf = nfDigits && eNf && eNf === nfDigits;
  const sameRom = romaneio && eRom && eRom.replace(/^0+/, '') === romaneio.replace(/^0+/, '');
  // Remove legado VP### - NF-… / duplicatas do mesmo NF/romaneio quando já vamos usar nome canônico
  if ((isLegacyVp && (sameNf || sameRom || (saleId && name.toUpperCase().startsWith(saleId.toUpperCase())))) ||
      (sameNf && k === 'nf') ||
      (sameRom && (k === 'pedido' || k === 'cp'))) {
    // Só marca trash se NÃO for exatamente o canônico que queremos manter
    const keep = incoming.some((f) => f.filename && baseName(f.filename) === name);
    if (!keep) trashIds.add(id);
  }
}

const results = [];

// Itens de lixeira (duplicatas / legado)
for (const e of existingItems) {
  const id = e.id || e.Id;
  if (id && trashIds.has(id)) {
    results.push({
      json: {
        action: 'trash',
        fileId: id,
        fileName: baseName(e.name || e.Name || ''),
        folderId
      }
    });
  }
}

// Uploads: só se o canônico ainda não existe (após trash, nomes legados somem)
for (const f of incoming) {
  const contentBase64 = f.contentBase64 || '';
  if (!contentBase64) continue;
  const fileName = f.filename || f.originalName || f.name;
  if (!fileName) continue;
  if (existingExact.has(fileName) && !trashIds.has(
    (existingItems.find((e) => baseName(e.name || e.Name || '') === fileName) || {}).id
  )) {
    // Já existe com o nome canônico — não reenviar
    continue;
  }

  const fileBuffer = Buffer.from(contentBase64, 'base64');
  if (!fileBuffer.length) continue;

  results.push({
    json: {
      action: 'upload',
      fileName,
      folderId,
      client: webhookBody.client,
      saleId: webhookBody.saleId,
      romaneioNumber: webhookBody.romaneioNumber || '',
      nfNumber: webhookBody.nfNumber || ''
    },
    binary: {
      data: await this.helpers.prepareBinaryData(
        fileBuffer,
        fileName,
        f.mimeType || 'application/octet-stream'
      )
    }
  });
}

return results;
